sys_script.script:
(function checkIdempotency() {
    var idempotencyKey = current.getValue('idempotency_key');

    gs.debug('[Retail Store Assistant] Check Idempotency: validating key "' + idempotencyKey + '"');

    if (!idempotencyKey) {
        gs.error('[Retail Store Assistant] Check Idempotency: rejected — idempotency_key is missing or empty');
        gs.addErrorMessage('Inventory Transaction rejected: idempotency_key is required.');
        current.setAbortAction(true);
        return;
    }

    var existing = new GlideRecord('x_1945330_retail_0_inv_txn');
    existing.addQuery('idempotency_key', idempotencyKey);
    existing.setLimit(1);
    existing.query();

    if (existing.hasNext()) {
        gs.warn('[Retail Store Assistant] Check Idempotency: duplicate detected — key "' + idempotencyKey + '" already exists');
        gs.addErrorMessage('Inventory Transaction rejected: idempotency_key "' + idempotencyKey + '" has already been posted. Duplicate inventory effects are not allowed.');
        current.setAbortAction(true);
    } else {
        gs.debug('[Retail Store Assistant] Check Idempotency: passed — key "' + idempotencyKey + '" is unique');
    }
})();
